solution.python:
import time
from functools import wraps


def timer(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        start = time.time()
        result = func(*args, **kwargs)
        end = time.time()
        print(f"{func.__name__} fonksiyonu {end - start:.4f}s sürdü")
        return result
    return wrapper


def cache(func):
    cache_dict = {}

    @wraps(func)
    def wrapper(*args):
        if args in cache_dict:
            return cache_dict[args]
        result = func(*args)
        cache_dict[args] = result
        return result
    return wrapper

solution.javascript:
function timer(func) {
    function wrapper(...args) {
        const start = performance.now();
        const result = func(...args);
        const end = performance.now();
        console.log(`${func.name} fonksiyonu ${((end - start) / 1000).toFixed(4)}s sürdü`);
        return result;
    }
    Object.defineProperty(wrapper, 'name', { value: func.name });
    return wrapper;
}


function cache(func) {
    const cacheMap = new Map();

    function wrapper(...args) {
        const key = JSON.stringify(args);
        if (cacheMap.has(key)) {
            return cacheMap.get(key);
        }
        const result = func(...args);
        cacheMap.set(key, result);
        return result;
    }
    Object.defineProperty(wrapper, 'name', { value: func.name });
    return wrapper;
}

solution.explanation_tr:
timer decorator'u: time.time() ile başlangıç ve bitiş zamanını ölçer, farkı yazdırır ve orijinal sonucu döndürür. Zaman: O(1) ek maliyet, Alan: O(1).

cache decorator'u: Closure ile bir dictionary tutar. Argümanları tuple olarak anahtar yapar. Cache hit varsa O(1)'de döndürür, yoksa fonksiyonu çalıştırır ve kaydeder. Fibonacci örneğinde O(2^n) olan karmaşıklığı O(n)'e düşürür. Zaman: Amortized O(1) lookup, Alan: O(n) - n benzersiz argüman sayısı.

@wraps(func) kullanımı, orijinal fonksiyonun __name__, __doc__ ve __module__ gibi metadata bilgilerini korur. Bu, debugging ve introspection için önemlidir.
